{"code": "# Bootstrap percentile CIs for descriptive rank correlations (seeded; article/design units resampled).
rng=np.random.default_rng(20260824)
def boot_spear(x,y,B=20000):
    x=np.asarray(x); y=np.asarray(y); n=len(x); vals=[]
    for _ in range(B):
        ii=rng.integers(0,n,n)
        if len(np.unique(x[ii]))>1 and len(np.unique(y[ii]))>1:
            vals.append(stats.spearmanr(x[ii],y[ii]).statistic)
    return np.quantile(vals,[.025,.975]),len(vals)
for label,d,y in [('bench rebound',b_er,'e_rebound_mean'),('bench zeta',b_z,'zeta_pct_mean'),('sim strain',ok,'peak_tendon_strain')]:
    ci,nb=boot_spear(d.t180_mean if 'bench' in label else d.t180, d[y])
    print(label, 'bootstrap 95% percentile CI',np.round(ci,3),'valid resamples',nb)

# Verify second-impact restitution identity claimed in the code documentation.
e_from_t=bench.t_second_ms_mean/1000*9.80665/(2*bench.in_dv_ms_mean)
print('\nmax absolute error in e = t_second*g/(2*v_in):',np.max(np.abs(e_from_t-bench.e_rebound_mean)))
print(pd.DataFrame({'specimen':bench.specimen,'reported_e':bench.e_rebound_mean,'derived_e':e_from_t}).to_string(index=False))", "display_text": "Quantifying uncertainty and verifying the bench restitution sign and definition"}

{"code": "# Audit quoted between/within spread claims under transparent definitions.
def spread_metrics(df,mean,sd):
    d=df.dropna(subset=[mean,sd]); rng=d[mean].max()-d[mean].min()
    pooled=np.sqrt(np.mean(d[sd]**2)); median_sd=d[sd].median()
    between_sd=d[mean].std(ddof=1)
    return {'n':len(d),'range':rng,'pooled_within_sd':pooled,'median_within_sd':median_sd,
            'range/pooled':rng/pooled,'range/median_sd':rng/median_sd,'between_sd/pooled':between_sd/pooled}
print('rebound all:',spread_metrics(bench,'e_rebound_mean','e_rebound_sd'))
print('rebound excluding high-noise amdjwm:',spread_metrics(bench[bench.specimen!='amdjwm'],'e_rebound_mean','e_rebound_sd'))
print('zeta:',spread_metrics(bench,'zeta_pct_mean','zeta_pct_sd'))
print('\narticle count in attachment:',len(bench),'unique:',bench.specimen.nunique(), 'total valid drops:',bench.n_valid.sum())", "display_text": "Checking article counts and between-versus-within spread claims under explicit definitions"}

